// Archive bytes against the oracle (lane ssa-archive). archive_oracle/fixtures.json holds, for aarch64-apple-darwin (the
// darwin archive kind) and x86_64-unknown-linux-gnu (gnu), the oracle's rlib and staticlibs of archive_oracle/nc.rs and
// their inputs (regenerated by hand with archive_oracle/regen.ts, which documents the builds). `ArArchiveBuilder` is fed
// the same members in the same order (the CGU objects as `RustObj`, `lib.rmeta`/`lib.rmeta-link` as `Other`, as
// `link_rlib` adds them), with the `ArchiveSymbols` `link_staticlib` passes for each `-Zstaticlib-*` flag, and must write
// the oracle's bytes. The `pub-*` builds (review ssa-archive F1) are the staticlib builds of a crate where hide changes the
// oracle's bytes (on nc.rs it does not: those symbols are already hidden), and the test asserts that it does, so that a
// port whose hide writes nothing cannot match. The fixtures are captured once, so the test does not run the oracle (no
// `.oracle.` in its name).
import { describe, expect, test } from "bun:test";
import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { DATA } from "../../../scripts/lib/common.ts";
import type { Session } from "../../rustc_session/session.ts";
import type { Target } from "../../rustc_target/spec/mod.ts";
import { DEFAULT_OBJECT_READER } from "../../vendor/ar_archive_writer/lib.ts";
import { ArArchiveBuilder, type ArchiveSymbols } from "./archive.ts";
import { apply_edits, collect_internal_names } from "./symbol_edit.ts";

interface Build {
  members: [string, string][];
  archive: string;
}
const FIXTURES = JSON.parse(readFileSync(join(import.meta.dir, "archive_oracle", "fixtures.json"), "utf8")) as {
  builds: Record<string, Record<string, Build>>;
  blobs: Record<string, string>;
};
const blob = (h: string): Uint8Array => Uint8Array.from(Buffer.from(FIXTURES.blobs[h]!, "base64"));

function sess(llvm_target: string, arch: string, archive_format: string): Session {
  const target = { llvm_target, arch: { $: arch }, options: { archive_format } } as unknown as Target;
  return {
    target,
    dcx: () => {
      throw new Error("unexpected diagnostic");
    },
  } as unknown as Session;
}

const TARGETS: Record<string, Session> = {
  "aarch64-apple-darwin": sess("arm64-apple-macosx11.0.0", "AArch64", "darwin"),
  "x86_64-unknown-linux-gnu": sess("x86_64-unknown-linux-gnu", "X86_64", "gnu"),
};

/** `crate_info.exported_symbols[StaticLib]`'s names: the two `#[no_mangle]` items of nc.rs. */
const EXPORTED = new Set(["nc_exported", "NC_DATA"]);
/** `crate_info.symbol_rename_suffix`: `.rs{:x}` of nc's `StableCrateId` (also in the CGU names). */
const RENAME_SUFFIX = ".rsc989f9563a4cdd83";
/** What `link_staticlib` passes to `build` for each build (`hide`/`rename` supported for ELF and Mach-O). */
const SYMBOLS: Record<string, ArchiveSymbols | undefined> = {
  rlib: undefined,
  plain: undefined,
  hide: { exported: EXPORTED, rename_suffix: undefined, hide: true },
  rename: { exported: EXPORTED, rename_suffix: RENAME_SUFFIX, hide: false },
  both: { exported: EXPORTED, rename_suffix: RENAME_SUFFIX, hide: true },
};

const WORK = join(DATA, "tmp", "archive-oracle-test", process.env.RUST_TS_AGENT ?? "default");

describe("ArArchiveBuilder writes the oracle's archives", () => {
  for (const [t, s] of Object.entries(TARGETS)) {
    for (const [b, build] of Object.entries(FIXTURES.builds[t]!)) {
      test(`${t} ${b}`, () => {
        const dir = join(WORK, t, b);
        rmSync(dir, { recursive: true, force: true });
        mkdirSync(dir, { recursive: true });
        try {
          const ab = ArArchiveBuilder.new(s, DEFAULT_OBJECT_READER);
          for (const [name, h] of build.members) {
            const p = join(dir, name);
            writeFileSync(p, blob(h));
            ab.add_file(p, name.endsWith(".o") ? "RustObj" : "Other");
          }
          const out = join(dir, b === "rlib" ? "libnc.rlib" : "libnc.a");
          expect(ab.build(out, SYMBOLS[b.replace(/^pub-/, "")])).toBe(true);
          expect(Buffer.from(readFileSync(out)).equals(Buffer.from(blob(build.archive)))).toBe(true);
        } finally {
          rmSync(dir, { recursive: true, force: true });
        }
      });
    }
  }
});

describe("the pub-* fixtures exercise hide", () => {
  for (const t of Object.keys(TARGETS)) {
    test(`${t}: the oracle's hide differs from plain, and both from rename`, () => {
      const a = (b: string): Buffer => Buffer.from(blob(FIXTURES.builds[t]![b]!.archive));
      expect(a("pub-hide").equals(a("pub-plain"))).toBe(false);
      expect(a("pub-both").equals(a("pub-rename"))).toBe(false);
    });
  }
});

describe("symbol_edit on the oracle's objects", () => {
  for (const t of Object.keys(TARGETS)) {
    const objs = FIXTURES.builds[t]!.plain!.members.map(([, h]) => blob(h));
    test(`${t}: collect_internal_names finds the CGU-crossing globals`, () => {
      const names = new Set<string>();
      for (const o of objs) collect_internal_names(o, EXPORTED, names);
      expect([...names].sort()).toEqual(["_RNvNtCshiMNQ7p2vRf_2nc1a6A_DATA", "_RNvNtCshiMNQ7p2vRf_2nc1a6helper"]);
    });
    test(`${t}: apply_edits leaves unedited input borrowed`, () => {
      // Nothing to hide (all exported) and nothing to rename: `Cow::Borrowed(data)`.
      for (const o of objs) expect(apply_edits(o, new Set(["nc_exported", "NC_DATA", "_RNvNtCshiMNQ7p2vRf_2nc1a6A_DATA", "_RNvNtCshiMNQ7p2vRf_2nc1a6helper"]), true, undefined)).toBe(o);
    });
  }
});
